    faq_a_bag_examples_list: "Μια νέα τσάντα έρχεται με παραδείγματα που μπορείτε να αλλάξετε ή να διαγράψετε όπως όλα τα άλλα: Σπίτι (ψώνια, συνταγές, γεύματα της εβδομάδας), Οικογένεια (μικρές στιγμές, μια λίστα για πάρτι γενεθλίων, δραστηριότητες και μαθήματα), Ιδέες (ιδέες για το Σαββατοκύριακο, ιδέες για δώρα ανά κατηγορία, και τι να κάνετε με τα χρήματα που αποταμιεύσατε) και Ταξίδια (μέρη που θέλετε να πάτε, τι παίρνουμε στο ταξίδι, βαλίτσα για ξενοδοχείο και μια λίστα για πτήση στο εξωτερικό). Μια τσάντα που υπήρχε ήδη παίρνει μία φορά τα νεότερα, μέσα στις δικές της τσέπες.",
    faq_q_bag_examples_list: "Ποια παραδείγματα έχει η τσάντα μου;",
    faq_a_nm_me1_guide: "Ο Sky – ο χαρακτήρας σας στο New Me, στην πρώτη του μορφή (Sky 1). Την πρώτη φορά, αμέσως μετά την εγγραφή, ανοίγει μια πύλη από φως με σπίθες ολόγυρα και ο Sky πετάει έξω από αυτήν, εξηγεί με λίγα πατήματα τι ακολουθεί και μετά μένει δίπλα σε κάθε ερώτηση: όσο επιλέγονται τα γεύματα, γράφει μαζί σας στο βιβλίο του, και ένα πάτημα στη συμβουλή του δείχνει άλλη μία. Στο τέλος ο Sky γιορτάζει μαζί σας και σας πηγαίνει μια σύντομη ξενάγηση – και όταν τελειώσει η ξενάγηση, έχει άλλη μία μικρή στιγμή μαζί σας. Αν φύγετε στη μέση – των ερωτήσεων ή της ξενάγησης – την επόμενη φορά ο Sky χαίρεται που σας βλέπει και ρωτά αν θα συνεχίσετε από το ίδιο σημείο.",
    faq_q_nm_me1_guide: "Ποιος σας οδηγεί στην είσοδο του New Me;",
    nm_m1_day_text: "Κάθε μέρα – ένα ✓ σε κάθε γεύμα, και εγώ τα μετράω όλα για εσάς.",
    nm_m1_go: "Πάμε",
    nm_m1_heart_btn: "Μαζί",
    nm_m1_heart_text: "Βήμα βήμα. Είμαι εδώ – πάντα.",
