    nm_m1_magic_text: "Και κάθε αληθινό σας βήμα μπροστά ανοίγει κι άλλα μέρη στον μαγικό κόσμο",
    nm_m1_menu_text: "Μαζί θα φτιάξουμε ένα μενού ακριβώς στα μέτρα σας: φαγητά που αγαπάτε, σε ώρες που σας βολεύουν.",
    nm_m1_portal: "Ένας νέος κόσμος ανοίγει",
