    nm_m1_ready_text: "Πρώτα μερικές μικρές ερωτήσεις – και μετά διαλέγουμε μαζί τα γεύματα.",
    nm_m1_skip: "Παράλειψη",
    nm_m1_tip_ai: "Ένα φαγητό που δεν είναι στη λίστα; Αργότερα, στην «Αλλαγή», μπορείτε να το γράψετε με δικά σας λόγια – και η AI θα το υπολογίσει. Και τώρα, ας διαλέξουμε μαζί τι θα τρώτε κάθε μέρα.",
    nm_m1_tip_love: "Κι αν κάτι δεν το αγαπάτε – μπορείτε πάντα να το αλλάξετε με την AI. Δεν έχει σημασία ποιο φαγητό – αν το αγαπάτε, μένει στο μενού.",
    nm_m1_tip_rice: "Το ρύζι το αγαπώ πιο πολύ απ' όλα – θα είναι η βάση μου, γι' αυτό θα το διαλέξω. Προτείνω να πάτε σε ό,τι είναι γνώριμο και νόστιμο.",
    faq_a_shop_basics: "Όταν η Λίστα Αγορών είναι εντελώς άδεια – για παράδειγμα ακριβώς στην αρχή – εμφανίζεται μια βασική λίστα για αρχή: γάλα, ψωμί, αυγά και άλλα. Ένα πάτημα σε ένα προϊόν το προσθέτει στη λίστα, και η «Προσθήκη όλων» τα προσθέτει όλα μαζί. Μόλις υπάρξει κάτι στη λίστα, η βασική λίστα εξαφανίζεται.",
    faq_q_shop_basics: "Τι είναι η βασική λίστα σε μια άδεια Λίστα Αγορών;",
    shop_basics_all: "Προσθήκη όλων",
    shop_basics_items: "γάλα|ψωμί|αυγά|ντομάτες|αγγούρια|τυρί|ρύζι|μακαρόνια|ελαιόλαδο|μήλα|μπανάνες|χαρτί υγείας",
    shop_basics_title: "Μια βασική λίστα για αρχή",
