    shop_win_other: "Άλλο…",
    shop_win_to: "Έως",
    room_genie_again_no: "Όχι τώρα",
    room_genie_again_no_msg: "Τότε ήρθε η ώρα να πετύχεις τους στόχους που έχεις ήδη βάλει. Όταν φτάσεις στον επόμενο – κάτι θα σε περιμένει εκεί ✨",
    room_genie_again_q: "Πάλι εδώ; ✨ Θα ήθελες να αλλάξεις κάτι ακόμα στη ζωή σου;",
    room_genie_again_yes: "Ναι",
    room_genie_bye: "Τα λέμε",
    room_genie_rest: "Το πνεύμα του δάσους ξεκουράζεται τώρα – έλα ξανά αύριο ✨",
    faq_a_shop_holidays: "Στη Λίστα Αγορών, πάτα το δώρο: εμφανίζονται με τη σειρά οι γιορτές της χώρας σου (αυτής που έχεις στις Ρυθμίσεις), με τις ημερομηνίες τους – που υπολογίζονται μόνες τους κάθε χρόνο. Πάτα μια γιορτή για μια έτοιμη λίστα με όσα αγοράζει ο κόσμος γι’ αυτήν· όλα είναι επιλεγμένα (εκτός από όσα είναι ήδη στη λίστα σου), ξετσέκαρε όσα δεν χρειάζεσαι και πάτα «Προσθήκη στη λίστα». Δύο εβδομάδες πριν από μια γιορτή εμφανίζεται μια μικρή κάρτα στην κορυφή της λίστας· το ✕ την κρύβει ως την επόμενη γιορτή.",
    faq_q_shop_holidays: "Πώς λειτουργεί το «Τι αγοράζουμε για τη γιορτή»;",
    shop_hol_add: "Προσθήκη στη λίστα ({n})",
    shop_hol_added: "Προστέθηκαν στη λίστα: {n}",
    shop_hol_btn: "Τι αγοράζουμε για τη γιορτή",
    shop_hol_items_title: "{holiday} – τι αγοράζουμε;",
    shop_hol_not_now: "Όχι τώρα",
    faq_a_shop_delivery: "Στη Λίστα Αγορών, πάτα το φορτηγάκι: διάλεξε τι έχει η παραγγελία (όλα είναι επιλεγμένα), πότε έρχεται – σήμερα, αύριο ή άλλη μέρα – και τι ώρα (πρωί, μεσημέρι, απόγευμα ή «Άλλο…» για δικές σου ώρες). Αυτά τα προϊόντα μεταφέρονται σε μια κάρτα «Στον δρόμο» στην κορυφή της λίστας, με τη μέρα και τις ώρες. Όταν έρθει η μέρα, εμφανίζεται το «Ήρθε η παραγγελία;» στη Μέρα μου (και η κάρτα έχει «Ήρθε;»). Αν ήρθαν όλα, πηγαίνουν στο «Αγορά ξανά». Αν κάτι λείπει, πάτα ό,τι δεν ήρθε και επιστρέφει κατευθείαν στη λίστα.",
    faq_a_shop_departments: "Η λίστα ταξινομείται μόνη της κατά τμήματα του σούπερ μάρκετ – φρούτα & λαχανικά, ψωμί, γαλακτοκομικά & αυγά, κρέας & ψάρι, παντοπωλείο, κατεψυγμένα, ποτά, σνακ, καθαριότητα, προσωπική φροντίδα, βρεφικά και κατοικίδια – για να περνάς τους διαδρόμους με τη σειρά. Το τμήμα αναγνωρίζεται από το όνομα του προϊόντος. Αν ένα προϊόν μπήκε σε λάθος θέση, πάτα το και διάλεξε το τμήμα του ή «Άλλο…» για να γράψεις δικό σου.",
    faq_a_shop_share_qty: "Ναι. Δίπλα σε κάθε προϊόν, το + προσθέτει ένα ακόμη (×2, ×3…) και το − αφαιρεί ένα. Το κουμπί κοινοποίησης στην κορυφή της Λίστας Αγορών στέλνει όλη τη λίστα, τακτοποιημένη ανά τμήμα, μέσω WhatsApp, email ή ως αντίγραφο.",
    faq_a_shop_two_buttons: "Και τα δύο σημαίνουν «αγοράστηκε». Το ✕ είναι για κάτι που αγοράζεις μία φορά – φεύγει από τη λίστα (και περιμένει στο αρχείο 🗑️ σε περίπτωση λάθους). Το ↺ είναι για όσα αγοράζεις ξανά και ξανά – φεύγουν από τη λίστα και περιμένουν στο «Αγορά ξανά»: το ανοίγει το μικρό κουμπί ↺ δίπλα στον κάδο, στο κάτω μέρος της λίστας, και ένα πάτημα εκεί επιστρέφει ένα προϊόν στη λίστα. Από την «Επεξεργασία» μέσα σε αυτό μπορείς να βγάλεις ένα προϊόν. Όταν προσθέτεις ένα προϊόν, όσα έχεις αγοράσει παλιότερα εμφανίζονται ως προτάσεις, κι αν είναι ήδη στη λίστα, απλώς γίνεται ×2 αντί για δεύτερη γραμμή.",
    faq_q_shop_delivery: "Πώς λειτουργεί το «Έκανα παραγγελία με παράδοση»;",
