    nm_demo_saved_2: "Γιαούρτι με γκρανόλα και φρούτα",
    nm_demo_title: "Πώς γίνεται μια αλλαγή",
    faq_a_new_me_challenge_journal: "Όταν τελειώνει μια πρόκληση – μεγάλη, μίνι ή η πρόκληση της εβδομάδας – στη γιορτή υπάρχει το κουμπί 📝 Πώς πήγε;, που ανοίγει μια σελίδα στο ημερολόγιο προκλήσεων: πώς ήταν (πέντε φατσούλες), τι βοήθησε, τι ήταν δύσκολο και τι κρατάω για τη συνέχεια – τίποτα δεν είναι υποχρεωτικό, και μπορεί να γίνει και αργότερα. Το ημερολόγιο είναι ένα διαμάντι στο μαγικό σακίδιο: κάθε πρόκληση που ολοκληρώθηκε με την ημερομηνία της και ό,τι γράφτηκε, η πιο πρόσφατη πρώτη – πάτα μία για να τη διαβάσεις, να την επεξεργαστείς ή να την κοινοποιήσεις (κοινοποιείται μόνο ό,τι υπάρχει στη σελίδα). Μια πρόκληση που ολοκληρώθηκε παίρνει επίσης ένα μετάλλιο στα επιτεύγματα, στις «Προκλήσεις που ολοκλήρωσα». Το ημερολόγιο προκλήσεων είναι ξεχωριστό από το συνηθισμένο ημερολόγιο.",
    faq_q_new_me_challenge_journal: "Τι είναι το ημερολόγιο προκλήσεων;",
