    faq_a_ai_reminder_in_text: "Ναι – γράψτε τη μαζί με την εργασία, για παράδειγμα «αύριο στις 17:00 παραλαβή δέματος, με υπενθύμιση μία ώρα πριν». Η υπενθύμιση αποθηκεύεται στην ίδια την εργασία: μία ώρα πριν, μισή ώρα, την προηγούμενη μέρα και ούτω καθεξής, και το «θύμισέ μου» χωρίς ώρα σημαίνει 10 λεπτά πριν. Μια υπενθύμιση γραμμένη στο κείμενο έχει προτεραιότητα έναντι του πεδίου υπενθύμισης στο ίδιο παράθυρο.",
    faq_q_ai_reminder_in_text: "Μπορώ να ζητήσω από τον βοηθό AI μια υπενθύμιση στο ίδιο αίτημα;",
    myday_meals_all_done: "Όλα τα γεύματα της ημέρας έχουν τσεκαριστεί 🍽️",
    nm_tour_week_text: "Μια μικρή πρόκληση για την εβδομάδα. ✓ κάθε μέρα – και στο τέλος ένα κλειδί.",
    books_home_chip: "{title} · σ. {page}",
    books_home_of: "από {total}",
    books_home_off_toast: "Το βιβλίο έφυγε από την αρχική οθόνη",
    books_home_on_toast: "Το βιβλίο είναι στην αρχική οθόνη 📖",
    books_home_pin: "Στην αρχική οθόνη",
    books_home_q: "Σε ποια σελίδα είμαι;",
    books_home_save: "Αποθήκευση",
    faq_a_books_home_chip: "Ναι. Στη Γωνιά ανάγνωσης, στην κάρτα ενός βιβλίου που διαβάζεις, άγγιξε το 📌 Στην αρχική οθόνη. Ένα μικρό κουμπί με το βιβλίο και τη σελίδα εμφανίζεται κάτω από τον χαιρετισμό στην αρχική οθόνη – άγγιξέ το, γράψε τον νέο αριθμό σελίδας και αποθήκευσε, και η πρόοδος καταγράφεται (και στη Γωνιά ανάγνωσης). Ένα ακόμα άγγιγμα στο 📌 το αφαιρεί. Μπορούν να υπάρχουν πολλά βιβλία μαζί – ένα κουμπί για το καθένα – και είναι το ίδιο σε κάθε συσκευή.",
    faq_a_new_me_week_challenge: "Μια μικρή πρόκληση για μία εβδομάδα, που τη διαλέγεις εσύ. Στον διάδρομο υπάρχει μια μεγάλη κάρτα: «Σε τι θέλεις να δουλέψεις αυτή την εβδομάδα;» – άγγιξέ την, διάλεξε έναν τομέα (με τον εαυτό μου, με τους άλλους, μάθηση και εξέλιξη, ηρεμία, μικρά βήματα θάρρους, σπίτι και ρουτίνα) και μια πρόκληση, και διάλεξε πότε ξεκινά. Οι ίδιες προκλήσεις υπάρχουν και στην οθόνη των προκλήσεων, στο 🌱 Προσωπική ανάπτυξη. Κάθε μέρα βάζεις ✓ στην κάρτα (μία ελεύθερη μέρα την εβδομάδα) και κάθε εβδομάδα που τελειώνει φέρνει ένα νέο κλειδί για τον μυστικό κόσμο. Το «Να διαβάζω 2 σελίδες τη μέρα» σημειώνεται μόνο του από τις σελίδες που καταγράφονται στη Γωνιά ανάγνωσης. Όταν τελειώσει η εβδομάδα, το 📌 Να μείνει ως καθημερινή εργασία την προσθέτει στη Ρουτίνα μου την ώρα που διαλέγεις, με ✓ κάθε μέρα. Τρέχει μία πρόκληση της εβδομάδας τη φορά· οι μεγάλες και οι μίνι προκλήσεις συνεχίζουν δίπλα της.",
    faq_a_room_genie: "Στη βεράντα μπροστά στη θάλασσα, ένα άγγιγμα στο λυχνάρι του Αλαντίν βγάζει το πνεύμα του δάσους – και ξεκινά μια συζήτηση: ποια είναι η ευχή σου (τι θα ήθελες να αλλάξεις στη ζωή σου), πώς θα νιώθεις όταν πραγματοποιηθεί, τι είναι δύσκολο στον δρόμο και πώς μπορεί η τωρινή κατάσταση να γίνει κάτι καλό. Μετά πόσο χρόνο θα πάρει περίπου, ένα πρώτο μικρό βήμα κι άλλα δύο, και ένα «αν… τότε…» για όταν δυσκολέψει. Στο τέλος εμφανίζεται ολόκληρη η ευχή βήμα βήμα, και μπορεί να γίνει στόχος στους Στόχους μου (τα βήματα γίνονται ορόσημα στο μονοπάτι, με ημερομηνία ανάλογα με τον χρόνο που διάλεξες· εκεί μπορούν να αλλάξουν όλα) ή να αποθηκευτεί στο ημερολόγιο – και τότε το πνεύμα αποχαιρετά. Τίποτα δεν αποθηκεύεται αν δεν επιλέξεις ένα από τα δύο. Από τη δεύτερη επίσκεψη και μετά, το πνεύμα ρωτά πρώτα αν θα ήθελες να αλλάξεις κάτι ακόμα στη ζωή σου: ναι – η ίδια συζήτηση· όχι τώρα – μια υπενθύμιση να πετύχεις τους στόχους που έχεις ήδη βάλει. Το πνεύμα βγαίνει μία φορά τη μέρα: αφού αποθηκευτεί μια ευχή (ή μετά το «Όχι τώρα»), ξεκουράζεται μέχρι αύριο. Οι ερωτήσεις ακολουθούν έναν γνωστό τρόπο να γίνει μια ευχή σχέδιο: ευχή, αποτέλεσμα, εμπόδιο και σχέδιο.",
    faq_q_books_home_chip: "Μπορώ να βλέπω το βιβλίο και τη σελίδα μου στην αρχική οθόνη;",
