    room_game_tag: "Στον δρόμο – σταματάμε και απολαμβάνουμε",
    room_drawer_aria: "Μικρό ντουλαπάκι",
    nm_me_choose: "Επιλογή",
    nm_me_on_screen: "Στην οθόνη",
    faq_a_new_me_game: "Στο New Me τα κουμπιά του παιχνιδιού μένουν πάντα στην ίδια θέση – στον διάδρομο, στο μυστικό δωμάτιο και παντού στο δάσος· αλλάζει μόνο η ζωγραφιά στη μέση. Πάνω: η μέρα της πορείας, τα κλειδιά, το σερί και η σημερινή ενέργεια (πόσο έχει φαγωθεί από το πρόγραμμα), και από κάτω η επόμενη αποστολή – το επόμενο γεύμα στην ώρα του (ένα πάτημα το ανοίγει, με το ✓ Το έφαγα). Στο πλάι: όλη η μέρα, προκλήσεις και η πορεία μου, και δίπλα τους η πρόκληση της εβδομάδας – οι 7 μέρες της και ένα ✓ για σήμερα. Κάτω: το μαγικό σακίδιο (ό,τι υπάρχει στο New Me – χάρτης του κόσμου, η πορεία μου, αγορές, επιτεύγματα, ημερολόγιο προκλήσεων, μετρήσεις, φωτογραφίες, μηνιαίο ημερολόγιο, ημερήσιος πίνακας, υπενθυμίσεις, μενού σε PDF και ρυθμίσεις· ανοίγει ως ξεχωριστή οθόνη). Ο χάρτης του κόσμου, το πρώτο πράγμα στο σακίδιο, δείχνει κάθε μέρος του δάσους – πατήστε ένα μέρος για να πάτε εκεί· σε ένα κλειδωμένο μέρος φαίνεται πόσα κλειδιά χρειάζεται. Ο Sky είναι ο χαρακτήρας σας στο μονοπάτι του δάσους: ξεκινά ως Sky 1, μετά από μερικές προκλήσεις (4 κλειδιά) μεγαλώνει σε Sky 2 και κοντά στο τέλος (9 κλειδιά) σε Sky 3 – με μια μεταμόρφωση που τη βλέπετε να συμβαίνει. Πατήστε τον Sky για να δείτε όλα τα στάδια – κάθε στάδιο που έχει ήδη επιτευχθεί μπορεί να επιλεγεί ξανά, οπότε ένα προηγούμενο μπορεί να επιστρέψει. Ο Sky αιωρείται – σύρεται με το δάχτυλο ή το ποντίκι και η είσοδος που αγγίζει ανοίγει (στην κλειδωμένη φαίνεται πόσα κλειδιά λείπουν). Ο Sky έρχεται επίσης μαζί σας σε κάθε δωμάτιο και μέρος και αιωρείται όπου τον αφήνετε: σύρετέ τον οπουδήποτε, και σύρετε τον φωτεινό δακτύλιο από κάτω του για να τον γυρίσετε εντελώς γύρω από τον εαυτό του· κοιτάζει προς την κατεύθυνση που κινείται (σε υπολογιστή: τα βέλη τον μετακινούν, τα Q και E τον γυρίζουν). Στον διάδρομο, το μικρό 🏠 κάτω από την επάνω γραμμή επιστρέφει στην αρχική οθόνη· σε κάθε δωμάτιο και μέρος, το κουμπί στην ίδια γωνία επιστρέφει στον διάδρομο.",
