    room_magic_song_rec3: "Καμπανάκια του καταρράκτη",
    faq_a_new_me_menu_build: "Πρώτα το ερωτηματολόγιο ρωτά ποια γεύματα τρώτε και πότε (2 γεύματα + ένα σνακ, 2 γεύματα + ένα ελαφρύ δείπνο ή και τα δύο) και αν υπάρχει κάτι το βράδυ – για φαγητό ή για ρόφημα, τι και τι ώρα. Με «2 γεύματα + ένα σνακ» τα γεύματα είναι μεσημεριανό (11:30) και βραδινό (19:00), με το σνακ στις 16:00. Μετά εμφανίζονται όλες οι επιλογές γι' αυτά τα γεύματα. Διαλέξτε έως 2 αγαπημένα για κάθε γεύμα – το μενού γράφει «αυτό ή εκείνο». Σε ορισμένες επιλογές (πίτα με άλειμμα, κορν φλέικς με γάλα, κάτι ελαφρύ) διαλέγετε έως 3 πράγματα που σας αρέσουν, το καθένα στη δική του μερίδα, και το μενού γράφει «αυτό ή εκείνο ή εκείνο»· οι θερμίδες ακολουθούν ό,τι διαλέξατε. Ο καφές και τα ροφήματα λειτουργούν με τον ίδιο τρόπο. Κάθε επιλογή είναι ισορροπημένη, ώστε η μέρα να βγαίνει ακριβώς 1.300 ή 1.500. Για να το αλλάξετε οποιαδήποτε στιγμή: ⚙️ Ρυθμίσεις → 🍽️ Φτιάξτε το μενού σας ή «Διαλέξτε έως 3 που σας αρέσουν» στην κάρτα του γεύματος.",
