    faq_a_myday_water_toggle: "Ναι. Το ποτήρι νερού στη Μέρα μου (με + για ένα ακόμη ποτήρι) εμφανίζεται από προεπιλογή. Για να το κρύψετε, απενεργοποιήστε το «Εμφάνιση του νερού στη Μέρα μου» στις Ρυθμίσεις > Εξατομίκευση & Ημερολόγιο. Δεν διαγράφεται τίποτα – η Παρακολούθηση Νερού συνεχίζει να λειτουργεί, και με την επανενεργοποίηση του διακόπτη το ποτήρι επιστρέφει.",
    faq_q_myday_water_toggle: "Μπορώ να κρύψω το νερό στη Μέρα μου;",
    myday_water_toggle_label: "Εμφάνιση του νερού στη Μέρα μου",
    faq_a_routine_newme_sync: "Με το New Me, το ⚙️ της Ρουτίνας μου έχει διακόπτη «Συγχρονισμός με το New Me». Όταν είναι ενεργός (προεπιλογή), τα σημερινά γεύματα του New Me εμφανίζονται στη Μέρα μου και στη Ρουτίνα μου – στη θέση των γευμάτων της ρουτίνας που κρύφτηκαν. Όταν είναι ανενεργός, τα γεύματα του New Me βγαίνουν και από τα δύο και η ρουτίνα επανέρχεται ακριβώς όπως ήταν. Τίποτα δεν διαγράφεται – η επανενεργοποίηση τα επαναφέρει όλα και ρωτά ποια γεύματα της ρουτίνας να κρυφτούν.",
    faq_q_routine_newme_sync: "Πώς ενεργοποιώ ή απενεργοποιώ τον συγχρονισμό του New Me με τη Ρουτίνα μου και τη Μέρα μου;",
