    faq_a_food_list_languages: "Η ενσωματωμένη λίστα τροφίμων ξεκίνησε με ισραηλινά φαγητά και τα εβραϊκά τους ονόματα. Σε όλες τις άλλες γλώσσες κάθε τρόφιμο εμφανίζεται με το αγγλικό του όνομα, και η αναζήτηση βρίσκει κάθε αγγλικό όνομα που γνωρίζει (για παράδειγμα το 'broth' βρίσκει το Clear soup)· τα τρόφιμα που έχουν μόνο εβραϊκό όνομα δεν εμφανίζονται εκεί. Ό,τι δεν υπάρχει στη λίστα μπορείτε απλώς να το γράψετε με δικά σας λόγια – η εκτίμηση με AI λειτουργεί σε κάθε γλώσσα.",
    faq_q_food_list_languages: "Γιατί η λίστα τροφίμων δείχνει αγγλικά ονόματα, και λιγότερα τρόφιμα, στη γλώσσα μου;",
    settings_copyright_line: "© 2026 με επιφύλαξη παντός δικαιώματος. ανάπτυξη εφαρμογής: eden zabari.",
    workout_ready_replace_btn: "Αντικατάσταση",
    faq_a_sport_workout_ai: "Στο «Οι προπονήσεις μου» → ⋯ → «Πρόγραμμα με AI» (και όταν ο πίνακας είναι άδειος, και στο πλακίδιο δίπλα στα έτοιμα προγράμματα). Απάντησε με λίγα αγγίγματα – πόσες φορές την εβδομάδα, πότε, μέρος, επίπεδο και στόχος, σχεδόν όλα έχουν και «Άλλο» – και, αν θέλεις, πρόσθεσε μια ελεύθερη γραμμή, όπως ευαίσθητο γόνατο ή 5 χλμ τρέξιμο ως το καλοκαίρι. Το AI φτιάχνει ολόκληρη εβδομάδα: είδη προπόνησης, μέρες, ώρες, διάρκεια, ένταση, ασκήσεις και μέρες ξεκούρασης. Πριν αποθηκευτεί οτιδήποτε, εμφανίζεται προεπισκόπηση: «Στον πίνακά μου» (αντί για τον πίνακα ή επιπλέον), «Άλλη πρόταση» (έως 3 φορές) ή «Αλλαγή απαντήσεων». Το πρόγραμμα είναι σκόπιμα μετριοπαθές, και αν αναφέρεις πόνο ή τραυματισμό, παίρνεις ήπιες επιλογές και τη συμβουλή να μιλήσεις με έναν επαγγελματία. Χρησιμοποιεί το ίδιο όριο AI με το πρόγραμμα ημέρας και τη ρουτίνα: 5 φορές δωρεάν και 60 τον μήνα με Premium.",
