    faq_a_new_me_magic_themes: "Πέντε λαμπερά θέματα που περιλαμβάνονται στο New Me: Μαγεμένο δάσος, Αστερόσκονη, Νεράιδα των ρόδων, Μαγικό σέλας και Χρυσό σούρουπο. Διάλεξε ένα μέσα στο New Me (⚙️ Ρυθμίσεις > Χρώματα) ή στις Ρυθμίσεις > Εμφάνιση & Οθόνη, και ένα πινέλο με γκλίτερ βάφει την οθόνη με αυτό. Ένα μαγικό θέμα προσθέτει λάμψεις σε όλη την εφαρμογή και σε κάθε άγγιγμα. Μπορείς να γυρίσεις σε οποιοδήποτε άλλο θέμα όποτε θέλεις.",
