    quotes_look_wall: "Τοίχος",
    theme_magic_section_label: "Μαγικά θέματα του New Me",
    apptour_focus_text: "Όλα παραμερίζουν εκτός από το ένα πράγμα του τώρα – με ένα μεγάλο ✓. Μετά εμφανίζεται το επόμενο.",
    apptour_m_presets_text: "Τα αποθηκευμένα γεύματά σας σε ένα μέρος: αναζήτηση, πρόσφατα, ανά ώρα της ημέρας – και το ＋ προσθέτει ένα στη σημερινή μέρα.",
    apptour_night_text: "Το 🌙 σκουραίνει όλη την εφαρμογή· το ☀️ φέρνει πίσω τη μέρα.",
    apptour_noteline_text: "Γράψτε και πατήστε ➤ – αποθηκεύεται στις σημειώσεις σας. Το 📝 στην αρχή αλλάζει σε 🛒 ψώνια ή 🍎 αποθηκευμένο γεύμα.",
    apptour_search_text: "Σημειώσεις, ψώνια, ημερολόγιο, συνταγές, τετράδια, στόχοι, πίνακες και βιβλία – μία αναζήτηση τα βρίσκει όλα.",
    faq_a_new_me_ai_menu: "Πριν από το μενού, το ερωτηματολόγιο ρωτά ποια γεύματα τρώτε και πότε (2 γεύματα + ένα σνακ, 2 γεύματα + ένα ελαφρύ δείπνο ή και τα δύο), αν τρώτε κάτι μικρό το βράδυ και τι ώρα, τι δεν τρώτε και πώς πίνετε καφέ ή τσάι. Μετά η AI ετοιμάζει 3 επιλογές για κάθε γεύμα – καθεμία στο μέγεθος του μεριδίου του γεύματος στη μέρα, ώστε η μέρα να βγαίνει πάντα ακριβώς 1.300 ή 1.500 – και ιδέες για ροφήματα, που αποθηκεύονται ως τα σταθερά σας ροφήματα. Διαλέξτε έως 2 αγαπημένα ανά γεύμα· οι επιλογές του αρχικού μενού είναι ακριβώς από κάτω, και στην 🔄 Αλλαγή εμφανίζονται μετά το προσωπικό σας μενού. Το 🔄 Άλλες επιλογές ετοιμάζει νέο σετ (3 φορές ανά ερωτηματολόγιο). Για να αλλάξετε απαντήσεις ή να ετοιμάσετε νέο μενού οποιαδήποτε στιγμή: ⚙️ Ρυθμίσεις → ✨ Προσωπικό μενού (AI).",
    faq_q_new_me_ai_menu: "Πώς λειτουργεί το προσωπικό μενού του New Me;",
    nm_ai_menu_building: "Ετοιμάζεται μενού για τα γεύματα και τις ώρες σας…",
