    nm_sales_premium: "Περιλαμβάνει όλο το Premium",
    nm_unlock_premium: "Και όλο το Premium ξεκλειδώθηκε επίσης.",
    settings_sub_status_newme: "Το Premium περιλαμβάνεται στο New Me σου.",
    room_back_to_shelf: "Στο ράφι",
    faq_a_new_me_day_total: "Κάθε μέρα βγαίνει ακριβώς όσο το πρόγραμμα: τα γεύματα, περίπου 150 θερμίδες για καφέ και ροφήματα μέσα στη μέρα και ό,τι επιλέχθηκε για το βράδυ – κάτι μικρό να φάτε ή κάτι να πιείτε. Για το βράδυ διαλέξτε έως 3 που σας αρέσουν (για παράδειγμα μια μπανάνα, ένα γιαούρτι ή 2 κομματάκια μαύρη σοκολάτα· ή τσάι βοτάνων, τσάι με λίγο γάλα ή ζεστό γάλα), και οι θερμίδες τους αφαιρούνται από τα γεύματα. Κάθε επιλογή ισορροπεί μόνη της: μια μικρότερη ή μεγαλύτερη επιλογή, ένα γεύμα που αφαιρέθηκε, το μικρό πρωινό και το μικρό γεύμα που έρχεται μαζί του ή το βράδυ – η διαφορά προστίθεται στα γεύματα ή αφαιρείται από αυτά, στο καθένα ανάλογα με το μέγεθός του, και κάτω από κάθε γεύμα γράφει πόσο (+ ή −) και τι να προστεθεί ή να μείνει έξω. Ένα γεύμα που έχει ήδη τσεκαριστεί μένει όπως καταγράφηκε. Στο ερωτηματολόγιο κάθε γεύμα δείχνει τη διόρθωσή του, και ένα μικρό πλαίσιο δείχνει γεύματα, ροφήματα, βράδυ και το σύνολο. Θέλετε κάτι άλλο εκείνη τη μέρα; Κρατήστε το σύνολο στις ίδιες θερμίδες ή λιγότερες.",
    faq_q_new_me_day_total: "Πώς βγαίνει μια μέρα του New Me ακριβώς 1.300 / 1.500, και πού μετράνε τα ροφήματα;",
