    books_quotes_chip: "Αποσπάσματα",
    faq_a_book_quotes: "Στο ράφι του μυστικού δωματίου (Αποσπάσματα) ή από το μικρό σήμα 💬 Αποσπάσματα στη Γωνιά ανάγνωσης – είναι η ίδια λίστα. Πάτησε «+ Απόσπασμα», γράψε τη φράση και διάλεξε το βιβλίο από τη Γωνιά ανάγνωσης ή γράψε άλλο τίτλο με το «✏️ Άλλο»· ο συγγραφέας είναι προαιρετικός. Το ✏️ επεξεργάζεται ένα απόσπασμα και το 🗑️ το διαγράφει. Τα αποσπάσματα είναι σελιδοδείκτες που σύρεις – το 🎨 πάνω αλλάζει σε φωτογραφίες ή σε τοίχο από κάρτες.",
    faq_a_room_wish_jar: "Στο ράφι του μυστικού δωματίου υπάρχει ένα γυάλινο βάζο για όνειρα. Πάτησε το μικρό βάζο στο πάνω ράφι (ή Ράφι > Το βάζο των ευχών) και γράψε πώς θα ήθελες να είναι η ζωή σου – όσο τρελά θέλεις, χωρίς σωστό ή λάθος. Κάθε ευχή διπλώνεται σε χαρτάκι και πέφτει στο βάζο. Το «Τράβα ένα χαρτάκι» ανοίγει ένα στην τύχη, και κάθε χαρτάκι ανοίγει και μόνο του. Από τη δεύτερη φορά που ανοίγεις την ίδια ευχή, μπορείς να την κάνεις στόχο και να τη χωρίσεις σε μικρά βήματα. Μία φορά την εβδομάδα εμφανίζεται απαλά ένα χαρτάκι με μία από τις ευχές σου – χωρίς πίεση, μόνο μια υπενθύμιση για το πού πηγαίνεις.",
    faq_q_book_quotes: "Πού κρατάω αποσπάσματα από βιβλία που αγάπησα;",
