    room_wish_written: "Γράφτηκε στις {date}",
    faq_a_saved_meals_page: "Τα αποθηκευμένα γεύματα έχουν δική τους σελίδα: Διατροφή και Μετρήσεις > ⭐ Αποθηκευμένα γεύματα (ή ⭐ στο μενού). Η αναζήτηση επάνω βρίσκει ένα γεύμα από το όνομα ή ένα υλικό, το «Πρόσφατα» δείχνει ό,τι πρόσθεσες τελευταία, και οι καρτέλες (Πρωινό, Μεσημεριανό, Βραδινό, Σούπες…) δείχνουν κάθε ώρα της μέρας. Το «+ Σήμερα» προσθέτει ένα γεύμα στον σημερινό Ημερήσιο Καταγραφέα Φαγητού, στην επόμενη ελεύθερη θέση. Πάτησε ένα γεύμα για επεξεργασία ή διαγραφή, και το ＋ επάνω προσθέτει νέο.",
