    presets_tab_snack: "Σνακ",
    presets_tab_soup: "Σούπες",
    presets_tab_sweet: "Γλυκίσματα",
    faq_a_notes_sticky_look: "Οι σημειώσεις είναι μια σύντομη λίστα από γυάλινες κάρτες – το 🎨 πάνω στις Σημειώσεις αλλάζει την εμφάνιση όλων των Σημειώσεων: τη λίστα, τα κουμπιά των ημερών επάνω και το παράθυρο όπου γράφεται μια σημείωση – γυαλί, απλή λίστα, καρτέλες ή ταινία washi. Μια σημείωση που σύρεται κρατά ακριβώς τη δική της εμφάνιση και το χρώμα της. Πάτησε το κείμενο μιας σημείωσης για να την ανοίξεις – εκεί μπορείς να την αλλάξεις, να αλλάξεις τα χρώματά της και να δεις πότε γράφτηκε τελευταία φορά. Πάτησε ○ όταν γίνει, και το × τη μετακινεί στο αρχείο (το 🗑️ στο κάτω μέρος της λίστας την επαναφέρει). Σύρε την από το ⠿ για να αλλάξεις τη σειρά, κάτω από το «Αργότερα» ή πάνω σε μια μέρα επάνω. Το ! σημειώνει μια σημείωση ως επείγουσα – ανεβαίνει απαλά στις πρώτες σειρές με μια μικρή ετικέτα «Επείγον»· ένα ακόμα πάτημα αφαιρεί τη σήμανση.",
    faq_q_notes_sticky_look: "Πώς ανοίγω, αλλάζω ή αφαιρώ ένα σημείωμα;",
    note_to_archive_btn: "Μετακίνηση στο αρχείο",
    faq_a_routine_clash: "Αν εκείνη την ώρα, τις ίδιες μέρες, υπάρχει ήδη κάτι, εμφανίζονται δύο επιλογές: «Αντικατάσταση» – το νέο παίρνει αυτή την ώρα και διαλέγετε άλλη ώρα για αυτό που υπήρχε (όταν επεξεργάζεστε κάτι που υπάρχει ήδη, προτείνεται η προηγούμενη ώρα του, ώστε τα δύο απλώς να ανταλλάξουν θέσεις), ή «Και τα δύο» – μένουν και τα δύο την ίδια ώρα, το ένα κάτω από το άλλο. Αν οι μέρες διαφέρουν (π.χ. το ένα Κυρ–Πέμ και το άλλο Παρασκευή), δεν ρωτάμε τίποτα.",
    faq_q_routine_clash: "Τι γίνεται αν βάλω κάτι στη ρουτίνα σε ώρα που είναι ήδη πιασμένη;",
    routine_clash_both: "✌️ Και τα δύο – και τα δύο στις {time}",
    routine_clash_move_btn: "Μεταφορά και αποθήκευση",
    routine_clash_move_to: "Σε ποια ώρα να μεταφερθεί το «{title}»;",
    routine_clash_replace: "🔄 Αντικατάσταση – και μεταφορά του «{title}» σε άλλη ώρα",
    routine_clash_title: "Στις {time} υπάρχει ήδη: {title}",
    faq_a_new_me_coffee: "Κάτω από το σημερινό μενού υπάρχει μια σύντομη σύνοψη: πόσες θερμίδες κάνουν όλα τα γεύματα της ημέρας, πόσες απομένουν για καφέ και ροφήματα, και κουμπιά για τον καφέ και τα ροφήματα που επιλέχθηκαν – ένα πάτημα το προσθέτει στα Ροφήματα. Στο «Διαλέξτε έως 3 που σας αρέσουν» κάτω από τα κουμπιά (και στο ερωτηματολόγιο) διαλέγετε τι εμφανίζεται: νερό / σόδα, τσάι βοτάνων, αναψυκτικό light, σκέτος / americano (~5), τσάι με λίγο γάλα (~25), καφές με νερό και έως 100 ml γάλα ή φυτικό ρόφημα (~50), ελαφριά ζεστή σοκολάτα, ζεστό γάλα ή κανονικός καφές / latte (~120).",
    faq_q_new_me_coffee: "Πού προσθέτω τον καφέ, και πώς ξέρω πόσα απομένουν για τη μέρα;",
    nm_coffee_black: "Σκέτος / americano χωρίς γάλα",
