    nm_late_idea_tea_honey: "Τσάι με ένα κουταλάκι μέλι",
    nm_late_idea_veg: "Κομμένα λαχανικά",
    nm_late_idea_warm_milk: "Ένα φλιτζάνι ζεστό γάλα",
    nm_late_idea_yogurt: "Γιαούρτι 0%",
    nm_late_ideas: "Για παράδειγμα: {ideas}",
    nm_late_ideas_none: "Σήμερα απομένουν πολύ λίγες – τσάι, νερό ή σκέτος καφές",
    nm_late_room_line: "Κάτι μικρό πριν τον ύπνο · απομένουν ~{n} θερμίδες σήμερα",
    faq_a_recipe_examples: "Κάτω από τις δικές σας συνταγές υπάρχουν παραδείγματα συνταγών: πρωινά, σαλάτες, σούπες, κυρίως πιάτα, συνοδευτικά, σνακ, επιδόρπια και vegan πιάτα, καθένα με τον χρόνο προετοιμασίας, τις θερμίδες ανά μερίδα και πόσα γραμμάρια ζυγίζει μία μερίδα. Πατήστε μια συνταγή για να την ανοίξετε, και το «Αποθήκευση στις Συνταγές Μου» φτιάχνει δικό σας αντίγραφο που μπορείτε να επεξεργαστείτε. Οι ετικέτες κατηγοριών φιλτράρουν, και ένα δεύτερο πάτημα στην ίδια ετικέτα δείχνει ξανά όλες.",
    faq_a_recipe_grams: "Μέσα σε μια συνταγή, δίπλα στις θερμίδες, γράφει «1 μερίδα ≈ X γρ.». Στις δικές σας συνταγές συμπληρώστε «Γραμμάρια ανά μερίδα» (και τον χρόνο προετοιμασίας αν θέλετε) στη φόρμα της συνταγής: και τα δύο είναι προαιρετικά, και ο χρόνος φαίνεται στη χρωματιστή λωρίδα της συνταγής.",
    faq_q_recipe_examples: "Τι είναι τα παραδείγματα συνταγών στις Συνταγές Μου;",
