    recipe_meta_minutes: "{n} λεπτά",
    recipe_minutes_placeholder: "Χρόνος προετοιμασίας (λεπτά)",
    recipe_save_example_btn: "Αποθήκευση στις Συνταγές Μου",
    recipe_saved_example: "✓ Αποθηκεύτηκε στις Συνταγές Μου",
    recipe_saved_example_toast: "Αποθηκεύτηκε στις Συνταγές Μου, εκεί μπορείτε να την επεξεργαστείτε",
    recipes_examples_title: "Παραδείγματα συνταγών",
    faq_a_recipe_scan_multi: "Ναι. Στην «Προσθήκη Συνταγής» πατήστε 📷 και επιλέξτε μία ή περισσότερες φωτογραφίες (έως 6· γίνεται και PDF). Η καθεμία εμφανίζεται σε μια σύντομη λίστα, όπου διαλέγετε τι δείχνει: Όλα, Υλικά ή Εκτέλεση, και το «➕ Άλλη μία φωτογραφία» προσθέτει κι άλλες. Μετά πατήστε «✨ Σάρωση συνταγής»: η AI τα ενώνει όλα σε μία συνταγή, με τη σωστή σειρά και χωρίς διπλές γραμμές, και μετράει ως μία σάρωση. Και πολλές φωτογραφίες που επιλέγονται από το 📷 Φωτογραφία στον βοηθό AI ανοίγουν εδώ.",
    faq_q_recipe_scan_multi: "Μπορώ να σαρώσω μία συνταγή από πολλές φωτογραφίες, π.χ. τα υλικά και την εκτέλεση χωριστά ή δύο σελίδες;",
    recipe_scan_add_more: "➕ Άλλη μία φωτογραφία",
    recipe_scan_part_all: "Όλα",
    recipe_scan_part_ingredients: "Υλικά",
    recipe_scan_part_steps: "Εκτέλεση",
    recipe_scan_remove_photo: "Αφαίρεση φωτογραφίας",
    recipe_scan_run_btn: "✨ Σάρωση συνταγής",
    recipe_scan_too_many: "Έως {n} φωτογραφίες ανά συνταγή",
    faq_a_note_written_at: "Πατήστε το κείμενο της σημείωσης για να την ανοίξετε. Μέσα, κάτω από το κείμενο, φαίνεται πότε γράφτηκε τελευταία φορά, με ακριβή ημερομηνία και ώρα. Ενημερώνεται μόνο όταν αλλάζει το ίδιο το κείμενο: η αρχειοθέτηση και η επαναφορά, το ✓, τα χρώματα ή η μετακίνηση της σημείωσης δεν το αλλάζουν.",
    faq_q_note_written_at: "Πώς βλέπω πότε έγραψα μια σημείωση;",
    note_written_at: "Γράφτηκε τελευταία: {date}",
    faq_a_new_me_month: "Στο μαγικό σακίδιο → Μηνιαίο ημερολόγιο: κάθε μέρα έχει χρώμα ανάλογα με το πόσα γεύματα τσεκαρίστηκαν, τα βέλη ‹ › αλλάζουν μήνα, και κάτω από το ημερολόγιο φαίνεται ο ημερήσιος μέσος όρος θερμίδων του μήνα. Ένα άγγιγμα σε μια μέρα δείχνει πόσα γεύματα τσεκαρίστηκαν και πόσες θερμίδες φαγώθηκαν εκείνη τη μέρα.",
    faq_q_new_me_month: "Πού βλέπω τον μήνα προς τα πίσω και τις μέσες θερμίδες στο New Me;",
    nm_month_avg: "Μέσος όρος μήνα: {kcal} θερμίδες την ημέρα · ημέρες με καταγραφή: {n}",
    nm_month_day_empty: "Δεν καταγράφηκε τίποτα αυτή τη μέρα.",
    nm_month_day_line: "Γεύματα με τσεκ: {checks} · θερμίδες: {kcal}",
    nm_extra_line_small: "{n} θερμίδες για αυτό το γεύμα, από το μικρό πρωινό – π.χ. {ideas}",
    faq_a_new_me_small_breakfast: "Ένα ελαφρύ πρωινό (περίπου 170 θερμίδες): μια πίτα από ζέα (έως 100 θερμίδες) με άλειμμα ή τυρί, μαζί με ένα λαχανικό – διαλέξτε έως 3 που σας αρέσουν, για παράδειγμα 1 κουταλάκι πραλίνα σοκολάτας, 1 κουταλάκι φυστικοβούτυρο ή μια φέτα κίτρινο τυρί (έως 22%). Επειδή είναι μικρό, μαζί του έρχεται «Και ένα μικρό γεύμα» σε άλλη ώρα (μιάμιση ώρα αργότερα, για παράδειγμα 11:30 → 13:00 – μπορεί να επιλεγεί και οποιαδήποτε άλλη ώρα): άλλη μία πίτα με άλειμμα, γιαούρτι πρωτεΐνης και φρούτο, ρυζογκοφρέτες και τυρί, δημητριακά με γάλα ή μισή πίτα και αυγά – έως περίπου 200 θερμίδες, με το δικό του ✓. Ό,τι περισσεύει ακόμα μοιράζεται στα υπόλοιπα γεύματα, και κάθε γεύμα δείχνει πόσο προστέθηκε, έτσι το σύνολο της ημέρας μένει όπως στο πρόγραμμα. Μπορείτε να το διαλέξετε στο ερωτηματολόγιο ή να το βάλετε μόνο για σήμερα με το 🔄 – για παράδειγμα όταν το πρωινό αργεί.",
