    weather_sky_storm: "Καταιγίδα",
    faq_a_ai_icon: "Ναι – στις Ρυθμίσεις > Εμφάνιση & Οθόνη. Η απαλή φούσκα είναι η προεπιλογή, και με το Premium μπορείτε να διαλέξετε επίσης έναν εγκέφαλο που αιωρείται ή ένα ρομπότ.",
    faq_a_new_me_favorites: "Ναι. Στο ερωτηματολόγιο (και όταν το ξανασυμπληρώνετε από τις ρυθμίσεις) μπορείτε να διαλέξετε έως 2 επιλογές για κάθε γεύμα. Η πρώτη εμφανίζεται στο μενού, με μια γραμμή «ή» από κάτω για τη δεύτερη – ένα άγγιγμα αλλάζει σε αυτήν μόνο για σήμερα. Κι αν το πρωινό δεν φαγώθηκε στην ώρα του, το «⏰ Αργότερα» το μεταφέρει αργότερα μέσα στη μέρα, χωρίς να αλλάξουν οι θερμίδες.",
    faq_a_theme_mode: "Μερικά ειδικά θέματα είναι πιο όμορφα σε σκοτεινή λειτουργία – Ακουαρέλα, Βόρειο Σέλας, Barbie και τα δύο θέματα με γκλίτερ – οπότε αν διαλέξετε ένα από αυτά η εφαρμογή περνά σε σκοτεινή λειτουργία, ενώ οποιοδήποτε άλλο θέμα (και ο πύραυλος) την περνά σε φωτεινή. Το Μαύρο και το Σκούρο Γκρι μένουν σκοτεινά. Μπορείτε πάντα να το αλλάξετε μετά με το 🌙 στο μενού ή με τη Φωτεινή Λειτουργία στις ρυθμίσεις.",
    faq_a_water_month: "Στην παρακολούθηση νερού. Κάθε καταχώριση στη σημερινή καταγραφή δείχνει την ώρα που προστέθηκε, και ο «Μηνιαίος πίνακας» ανοίγει όλο τον μήνα: κάθε μέρα δείχνει πόσα λίτρα ήπιατε (✓ όταν επιτεύχθηκε ο ημερήσιος στόχος), και ένα άγγιγμα σε μια μέρα δείχνει τις καταχωρίσεις της με τις ώρες τους.",
    faq_q_ai_icon: "Μπορώ να αλλάξω το εικονίδιο του βοηθού AI;",
