    faq_a_new_me_weight_optional: "Όχι. Τόσο το τρέχον βάρος όσο και το βάρος-στόχος στο ερωτηματολόγιο είναι προαιρετικά. Αν αργότερα προστεθεί ζύγισμα (⚖️ Βάρος στο «Η πορεία μου» του New Me ή στην παρακολούθηση βάρους), η πρόοδος μετριέται από το πρώτο.",
