    room_reveal_star: "Ένα νέο αστέρι άναψε στο τηλεσκόπιο στην ταράτσα ✨",
    faq_a_room_records: "Το πικάπ βρίσκεται στο δωμάτιο από την αρχή, πάνω στο κούτσουρο δίπλα στην πολυθρόνα. Οι δίσκοι του ανοίγουν στο YouTube τα επίσημα βίντεο μεγάλων επιτυχιών των τελευταίων χρόνων, και από κάτω υπάρχουν πέντε ήρεμες μελωδίες που παίζουν εδώ στο δωμάτιο – ο δίσκος γυρίζει όσο παίζουν, και το «⏹ Διακοπή» σταματά τη μουσική.",
    faq_a_room_roof_gifts: "Έρχονται με το 8ο κλειδί. Ένα άγγιγμα στο τηλεσκόπιο σου επιτρέπει να κοιτάξεις μέσα από αυτό: ο νυχτερινός ουρανός από κοντά – σύρε (ή χρησιμοποίησε τα βελάκια) για να κοιτάξεις γύρω – και οι προκλήσεις που ολοκληρώθηκαν σχηματίζουν μέσα του έναν αστερισμό, ένα αστέρι για κάθε πρόκληση· ένα άγγιγμα σε αστέρι δείχνει ποια ήταν. Ένα άγγιγμα στο μικρό σεντούκι το ανοίγει – προς το παρόν είναι άδειο – και ένα ακόμα άγγιγμα το κλείνει.",
