    faq_a_new_me_preview: "Ναι. Η σελίδα του New Me ξεκινά με ένα σύντομο βίντεο για όσα συμβαίνουν μέσα: το ερωτηματολόγιο, οι λάμπες στον διάδρομο, το σακίδιο, οι προκλήσεις και τα κλειδιά. Από κάτω υπάρχουν όλα όσα περιλαμβάνει, μια ματιά σε μία μέρα και σύντομες απαντήσεις.",
