    ai_chat_food_invalid: "Οι θερμίδες πρέπει να είναι αριθμός πάνω από 0",
    ai_chat_food_updated: "Ενημερώθηκε:",
    faq_a_ai_chat_food_fix: "Ναι. Κάτω από την απάντηση στη συνομιλία πατήστε ✏️ Διόρθωση θερμίδων / πρωτεΐνης, αλλάξτε τους αριθμούς και πατήστε Αποθήκευση. Αλλάζει μόνο ό,τι μόλις προστέθηκε – ακόμη κι αν ενώθηκε με ένα σνακ που υπήρχε ήδη. Η AI μπορεί να κάνει λάθη, οπότε αξίζει ένας γρήγορος έλεγχος.",
    faq_a_new_me_home_btn: "Αν έχετε New Me, ένα μικρό 💎 δίπλα στη λειτουργία εστίασης, στο πάνω μέρος της αρχικής οθόνης, ανοίγει το σημερινό μενού. Τα σημερινά γεύματα εμφανίζονται και στη Μέρα μου, το καθένα με ✓.",
    faq_a_routine_item_days: "Ναι. Πατήστε το στοιχείο στη Ρουτίνα μου και επιλέξτε τις μέρες του στο 📅 Ημέρες – για παράδειγμα μόνο Δευτέρα έως Παρασκευή. Τις άλλες μέρες δεν εμφανίζεται στη Μέρα μου και δεν έχει ✓· στη Ρουτίνα μου μένει, πιο αχνό, με τις μέρες του δίπλα. Η κάρτα που ρωτά για ένα στοιχείο μετά από 3 μέρες χωρίς ✓ μετρά μόνο τις δικές του μέρες.",
    faq_q_ai_chat_food_fix: "Μπορώ να διορθώσω θερμίδες ή πρωτεΐνη αφού ο βοηθός καταγράψει φαγητό;",
    faq_q_new_me_home_btn: "Πού είναι το New Me στην αρχική οθόνη;",
    faq_q_routine_item_days: "Μπορεί ένα στοιχείο στη Ρουτίνα μου να ισχύει μόνο κάποιες μέρες;",
    routine_item_days_label: "📅 Ημέρες",
    home_note_meal_ph: "Βρες ένα αποθηκευμένο γεύμα…",
    menu_quick_search: "Γρήγορη αναζήτηση",
    nm_times_hint: "Συμβουλή: μπορείτε να βάλετε την πιο αργή ώρα που τρώτε συνήθως κάθε γεύμα – π.χ. 9:00 αν συχνά τρώτε γύρω στις 8.",
    room_game_marquee: "Στον δρόμο – σταματάμε και απολαμβάνουμε",
    room_sand_erase_aria: "Τρίψε για να σβήσεις το γραπτό",
    faq_a_home_note_line: "Γράψε στη γραμμή στη μέση της αρχικής οθόνης και πάτα ➤ (ή Enter) – αποθηκεύεται στις Σημειώσεις. Πάτα το 📝 στην αρχή της γραμμής και γίνεται 🛒: τότε ό,τι γράφεις πηγαίνει στη Λίστα Αγορών. Πάτα άλλη μία φορά για 🍎: γράψε λίγα γράμματα, εμφανίζονται τα αποθηκευμένα γεύματα που ταιριάζουν, και ένα πάτημα καταγράφει ένα στα σημερινά γεύματα. Με το 🎤 μπορείς απλώς να το πεις.",
    faq_a_night_mode: "Άνοιξε το μενού ☰ και πάτα 🌙 επάνω – όλη η εφαρμογή γίνεται σκούρα. Το ☀️ στο ίδιο σημείο φέρνει πίσω τη μέρα. Υπάρχει και στις Ρυθμίσεις, στη Φωτεινή Λειτουργία.",
    faq_q_home_note_line: "Πώς γράφω μια γρήγορη σημείωση από την αρχική οθόνη;",
    faq_q_night_mode: "Πώς περνάω σε νυχτερινή λειτουργία;",
    menu_day_mode: "Ημερήσια λειτουργία",
    menu_night_mode: "Νυχτερινή λειτουργία",
    faq_a_secret_room_yoga: "Στο τέλος του μονοπατιού στο δάσος υπάρχει μια λαμπερή πύλη, και πίσω της, δίπλα σε έναν καταρράκτη, τα πλάσματα του δάσους – Λούμι, Πάφι, Νίξι και Σπάρκλετ – κάθονται στα στρωματάκια τους σε ημικύκλιο, και η Φλόρα, η δασκάλα της γιόγκα, κάθεται απέναντί τους στο μοναχικό στρωματάκι πάνω στην πέτρα. Πάτα τη Φλόρα: ανοίγει τα μάτια της, όλα έρχονται κοντά και η κουβέντα ξεκινά αργά, με χρόνο για διάβασμα – η Φλόρα ρωτά πώς είναι όλοι, κάθε πλάσμα απαντά με τη δική του φωνή (με μια μικρή εικόνα όποιου μιλά δίπλα σε κάθε γραμμή), και μετά ρωτά εσένα πώς νιώθεις με τους κοντινούς σου ανθρώπους. Η κουβέντα συνεχίζει ανάλογα με τις απαντήσεις σου – καλοί άνθρωποι, κάποιος δύσκολος ή λίγη μοναξιά. Κάθε δρόμος καταλήγει σε μια μικρή αποστολή (μπορεί να μπει κατευθείαν στη Μέρα μου· όταν η αποστολή είναι να γράψεις κάτι, υπάρχει χώρος για να το γράψεις, και αποθηκεύεται στο μαγικό ημερολόγιο) και σε μια στάση με τρεις ανάσες μαζί. Το ↩ γυρίζει ένα βήμα πίσω και το ✦ ξεκινά νέα κουβέντα. Το επόμενο κλειδί ανοίγει τον καταρράκτη: όταν κάθεσαι στην πέτρα, όλα εξαφανίζονται και μένει μόνο ο ήχος του νερού. Όταν σκύβεις πάνω από τη λιμνούλα, μια ερώτηση αναδύεται από το νερό – τι θα έκανε σήμερα ο αληθινός σου εαυτός; – και η απάντηση γίνεται μια μικρή δουλειά στη Μέρα μου. Είναι μια τρυφερή στιγμή, όχι υποκατάστατο μιας συζήτησης με ειδικό.",
    faq_q_secret_room_yoga: "Τι γίνεται στη γιόγκα στο δάσος;",
    room_back_to_forest: "Πίσω στο μονοπάτι",
    room_back_to_yoga: "Πίσω στη γιόγκα",
    room_item_waterfall: "Ο καταρράκτης",
    room_waterfall_pool_aria: "Άγγιξε το νερό",
    room_waterfall_rock_aria: "Κάτσε στον βράχο",
    room_yoga_guide_aria: "Μίλα με τη Φλόρα",
