    nm_time_hour: "Ώρα",
    nm_time_minutes: "Λεπτά",
    routine_time_taken: "Υπάρχει ήδη κάτι αυτή την ώρα: {title}",
    faq_a_new_me_times: "Στο ερωτηματολόγιο της αρχής και οποτεδήποτε στις ρυθμίσεις του New Me → «Ώρες γευμάτων». Αν η ρουτίνα σας έχει ήδη ώρες γευμάτων, λαμβάνονται από εκεί – και τα γεύματα της ρουτίνας μπορούν να κρυφτούν, με τα γεύματα του New Me στη θέση τους. Αν όχι, διαλέγετε πόσα γεύματα την ημέρα (2 γεύματα + ένα σνακ / 2 γεύματα + ένα ελαφρύ δείπνο / 2 γεύματα + ένα σνακ + ένα ελαφρύ δείπνο) και πότε το καθένα. Με «2 γεύματα + ένα σνακ» είναι μεσημεριανό στις 11:30, σνακ στις 16:00 και βραδινό στις 19:00 (το καθένα μπορεί να αλλάξει). Αυτές είναι οι ώρες των γευμάτων σας παντού: στον διάδρομο, στη Μέρα μου, στη Ρουτίνα μου και στις υπενθυμίσεις. Ό,τι κι αν επιλεγεί, οι θερμίδες της μέρας μένουν ίδιες: ό,τι αφαιρείται μοιράζεται στα υπόλοιπα γεύματα.",
    faq_q_new_me_times: "Πώς ορίζω τις ώρες των γευμάτων μου στο New Me;",
    nm_times_count: "Πόσα γεύματα την ημέρα;",
