    routine_daysoff_what: "Και ποια είναι η ρουτίνα αυτές τις μέρες;",
    routine_daysoff_which: "Ποιες μέρες;",
    faq_a_secret_room_diary: "Μόνο εσύ. Οι σελίδες του ημερολογίου αποθηκεύονται στον λογαριασμό σου, οπότε υπάρχουν σε κάθε συσκευή και κανείς άλλος δεν τις βλέπει. Το ανοίγει το μαγικό ημερολόγιο πάνω στο γραφείο του μυστικού δωματίου, αλλά και το ημερολόγιο στη γωνιά της μουσικής. Κάτω από τη νέα σελίδα υπάρχει ένας διπλωμένος μηνιαίος πίνακας: μια τελεία σημαδεύει κάθε μέρα που έχει σελίδα, και ένα άγγιγμα σε μια μέρα ανοίγει τις σελίδες της – εκεί μπορείς και να διαγράψεις σελίδα. Όταν το ημερολόγιο είναι πια ανοιχτό, μπορεί να προστεθεί και στο κύριο μενού – με τον διακόπτη μέσα στο ίδιο το ημερολόγιο ή στις ρυθμίσεις του New Me.",
    faq_a_secret_room_places: "Κάθε είσοδος στην πύλη του δάσους ανοίγει με το δικό της κλειδί. Πίσω τους: η βεράντα μπροστά στη θάλασσα (πάνω στο τραπεζάκι το λυχνάρι του Αλαντίν – ένα άγγιγμα, και ένα πνεύμα του δάσους αναδύεται από αυτό μέσα σε μια μαγική ομίχλη, στροβιλίζεται γύρω γύρω και ξεκινά μια συζήτηση για την ευχή σου – δες «Τι κάνει το τζίνι του λυχναριού;»), η κιθάρα και το ημερολόγιο (η κιθάρα παίζει μια σύντομη, ήρεμη μελωδία και σταματά μόνη της, και καθένας από τους τρεις δίσκους που κρέμονται στο δέντρο παίζει τη δική του μαγική μελωδία – ένα ακόμα άγγιγμα τη σταματά – και στο ημερολόγιο πάνω στο κούτσουρο γράφεις), το δωμάτιο της αναπνοής (μια ήσυχη λίμνη στο ηλιοβασίλεμα – στο νερό επιπλέει ένα φαναράκι λωτού: άγγιξέ το, γράψε μια ευχή, και απομακρύνεται μαζί της, πολύ πίσω μέσα στη λίμνη· με το μαγικό ραβδί μπορείς να γράψεις στην άμμο ό,τι θέλεις να αφήσεις να φύγει, και μένει εκεί μέχρι να το σβήσεις με το δάχτυλο) και το μονοπάτι στο δάσος (ανοίγει τη νύχτα, και ένα άγγιγμα στα φανάρια το αλλάζει σε μέρα· στο παγκάκι κάθεσαι, και ένα άγγιγμα στην πινακίδα τη φέρνει κοντά – ένας πίνακας με έξι μικρές ερωτήσεις για τσεκάρισμα). Σε μια κλειδωμένη είσοδο φαίνεται πόσα κλειδιά απομένουν. Στο τέλος του μονοπατιού, μια λαμπερή πύλη οδηγεί στη γιόγκα δίπλα στον καταρράκτη – κι από εκεί, στον ίδιο τον καταρράκτη.",
