    dictation_btn_aria: "Μίλα και γράφεται",
    dictation_mic_denied: "Το μικρόφωνο είναι μπλοκαρισμένο – επίτρεψέ το από το 🔒 δίπλα στη διεύθυνση στο πρόγραμμα περιήγησης ή στις ρυθμίσεις του τηλεφώνου",
    faq_a_dictation: "Ναι – πάτα το μικρόφωνο 🎤 στη γωνία της γρήγορης σημείωσης ή μιας σελίδας γραφής στο τετράδιο και μίλα: οι λέξεις γράφονται όσο μιλάς, στη γλώσσα της εφαρμογής. Πάτα ξανά για διακοπή. Την πρώτη φορά, το πρόγραμμα περιήγησης ζητά άδεια για το μικρόφωνο. Λειτουργεί σε Chrome / Android και σε Safari στο iPhone. Στον υπολογιστή χρειάζεσαι μικρόφωνο και ένα πρόγραμμα περιήγησης όπως Chrome, Edge ή Safari – αν λείπει κάτι, το μήνυμα λέει ακριβώς τι.",
    faq_q_dictation: "Μπορώ να μιλάω αντί να πληκτρολογώ;",
    faq_a_secret_room: "Ένα δωμάτιο μόνο δικό σας, μέσα στο New Me – ένα σπίτι μέσα σε ένα γιγάντιο δέντρο. Βλέπετε έναν τοίχο τη φορά και γυρίζετε με τα βέλη (ή σύροντας). Το πρώτο κλειδί έρχεται μετά από ✓ σε γεύμα σε 3 διαφορετικές μέρες και ανοίγει την πόρτα – και μαζί όλο το δωμάτιο: τον υπολογιστή, το παιχνίδι, το πικάπ, το ράφι με τη βιβλιοθήκη μέσα και τη γάτα. Μετά, κάθε πρόκληση που ολοκληρώνεται (και η πρόκληση της εβδομάδας) δίνει ένα κλειδί που ανοίγει το επόμενο μέρος: την ταράτσα των αστεριών, τη βεράντα μπροστά στη θάλασσα, την κιθάρα και το ημερολόγιο, το δωμάτιο της αναπνοής, το μονοπάτι στο δάσος με τη γιόγκα, τον καταρράκτη και μια έκπληξη στην ταράτσα – και η 8η φέρνει ένα μπουκάλι από τη θάλασσα με το γράμμα από το παρελθόν μέσα. Όταν κάτι ανοίγει, ένα βέλος δείχνει τον δρόμο. Ανοίγει και η μικρή πόρτα στο κάτω μέρος της μηχανής του παιχνιδιού – προς το παρόν το ντουλαπάκι πίσω της είναι άδειο. Στην ταράτσα των αστεριών, ένα αστέρι που αγγίζετε πέφτει σαν διάττοντας, και η γάτα κάθεται στο μαξιλάρι.",
