    room_wall_window_title: "Το παράθυρο και ο υπολογιστής",
    faq_a_steps_in_sport: "Στην κορυφή της Παρακολούθησης Προπόνησης, σε μια μικρή λωρίδα: τα βήματα σήμερα και αυτή την εβδομάδα. Τα βήματα θα μετριούνται αυτόματα μόλις η εφαρμογή συνδεθεί με το Google Fit / Apple Health στην έκδοση για κινητό – το κουμπί 🔗 δίπλα το εξηγεί.",
    faq_q_steps_in_sport: "Πού είναι ο μετρητής ημερήσιων βημάτων;",
    sport_steps_today_label: "βήματα σήμερα",
    sport_steps_week_label: "αυτή την εβδομάδα",
    faq_a_reminders_one_place: "Κάθε υπενθύμιση έρχεται μία φορά, σε ένα μέρος. Αν η εφαρμογή είναι ανοιχτή μπροστά σου (στον υπολογιστή, στο iPad ή στο κινητό), εμφανίζεται εκεί· αλλιώς έρχεται ως ειδοποίηση μόνο στο κινητό. Το '✅ Έγινε, ευχαριστώ!' ή το 'Κατάλαβα!' οπουδήποτε την κλείνει σε όλες τις συσκευές, και δεν ξαναέρχεται. Το 'Όχι ακόμα' την αναβάλλει: ξαναέρχεται κάθε 5 λεπτά, κάθε φορά σε ένα μέρος. Το ✓ στην εργασία μέσα στη λίστα μετράει επίσης ως ολοκληρωμένο. Για να παίρνεις τις ειδοποιήσεις και σε υπολογιστή και tablet, άνοιξε το 'Και σε υπολογιστή και tablet' στις Ρυθμίσεις > Ειδοποιήσεις.",
    faq_q_reminders_one_place: "Γιατί μια υπενθύμιση έρχεται μόνο μία φορά και μόνο στο κινητό;",
    reminder_all_devices_hint: "Από προεπιλογή κάθε υπενθύμιση έρχεται μία φορά, σε ένα μέρος: στο κινητό ή στη συσκευή όπου η εφαρμογή είναι ανοιχτή μπροστά σου. Το Έγινε ή το Κατάλαβα σε ένα μέρος την κλείνει παντού.",
    reminder_all_devices_label: "Και σε υπολογιστή και tablet",
    myday_water_info: "8 μεσαία / μικρά ποτήρια νερό είναι κατά μέσο όρο περίπου 2 λίτρα",
    faq_a_good_things: "Το βράδυ (από τις 18:00) εμφανίζεται ένα μικρό κουμπί κάτω από την ημερομηνία: γράψτε έως 3 καλά πράγματα που έγιναν σήμερα – αρκεί ακόμα και ένα. Αποθηκεύονται, και στις «Προηγούμενες μέρες» βλέπετε τι γράψατε παλιότερα. Το «Όχι απόψε» το κρύβει ως αύριο, και μπορείτε να το απενεργοποιήσετε εντελώς στις Ρυθμίσεις > Εξατομίκευση & Ημερολόγιο.",
    faq_a_home_countdown: "Σημειώστε ένα γεγονός με ⭐ στο ημερολόγιο (το αστέρι δίπλα του στη λίστα γεγονότων). Το πλησιέστερο σημειωμένο γεγονός μέσα στις επόμενες 100 μέρες εμφανίζεται κάτω από την ημερομηνία – «Σε 3 μέρες · Γενέθλια της μαμάς», «Αύριο · …» ή «Σήμερα · …». Πατήστε το για να πάτε σε εκείνη τη μέρα στο ημερολόγιο.",
    faq_a_home_streak: "Μετράει πόσες μέρες στη σειρά είχατε τουλάχιστον ένα ✓ – οτιδήποτε στη Μέρα μου, στη Ρουτίνα μου, στους Στόχους μου ή στο New Me. Εμφανίζεται από τις 2 μέρες. Αν σήμερα δεν υπάρχει ακόμα ✓, το σερί δεν έχει σπάσει – υπάρχει ακόμα όλη η μέρα. Κι αν τελειώσει, απλώς εξαφανίζεται ήσυχα, χωρίς ενοχές.",
    faq_a_home_weather: "Ενεργοποιήστε το «Ο καιρός στον ουρανό της αρχικής οθόνης» στις Ρυθμίσεις > Εξατομίκευση & Ημερολόγιο και επιτρέψτε την τοποθεσία. Τότε ο ουρανός της αρχικής οθόνης δείχνει τον πραγματικό καιρό εκεί που βρίσκεστε – ήλιο (ή φεγγάρι και αστέρια τη νύχτα), σύννεφα, βροχή, χιόνι, καταιγίδα ή ομίχλη – σε κάθε θέμα, με ενημέρωση περίπου κάθε 40 λεπτά. Η κατά προσέγγιση τοποθεσία (στρογγυλεμένη σε περίπου 1 χλμ.) μένει μόνο στη συσκευή σας και ελέγχεται μέσω του διακομιστή μας στο MET Norway. Από προεπιλογή είναι απενεργοποιημένο. Κάτω από τον διακόπτη γράφει τι καιρό κάνει έξω τώρα – για παράδειγμα ⛅ Μερικώς νεφελώδης, γι' αυτό ο ουρανός δείχνει και ήλιο και σύννεφα.",
    faq_q_good_things: "Τι είναι τα «3 καλά πράγματα από σήμερα»;",
