    settings_weather_hint: "Βροχή, σύννεφα ή χιόνι στο φόντο της αρχικής οθόνης, ανάλογα με τον καιρό εκεί που βρίσκεστε. Η κατά προσέγγιση τοποθεσία μένει σε αυτή τη συσκευή και ελέγχεται μέσω του διακομιστή μας στο MET Norway.",
    settings_weather_label: "Ο καιρός στον ουρανό της αρχικής οθόνης",
    weather_failed: "Δεν ήταν δυνατός ο έλεγχος του καιρού αυτή τη στιγμή.",
    weather_location_denied: "Δεν υπάρχει πρόσβαση στην τοποθεσία – επιτρέψτε την στις ρυθμίσεις του προγράμματος περιήγησης και δοκιμάστε ξανά.",
    faq_a_home_focus: "Πατήστε ◎ στο πάνω μέρος της αρχικής οθόνης: όλα εξαφανίζονται εκτός από το ένα πράγμα για τώρα – ό,τι έχει αυτή την ώρα ή το επόμενο της σημερινής λίστας – με ένα μεγάλο ✓, και τις Γρήγορες Σημειώσεις. Μετά το ✓ εμφανίζεται το επόμενο. Πατήστε «Λειτουργία εστίασης ✕» πάνω για να επιστρέψουν όλα.",
    faq_a_home_search: "Άνοιξε το μενού ☰ – η αναζήτηση είναι ακριβώς επάνω. Γράψε τουλάχιστον 2 γράμματα: τα αποτελέσματα έρχονται από τις σημειώσεις, τη λίστα αγορών, το ημερολόγιο, τις συνταγές, τα τετράδια (τίτλοι και κείμενο σελίδων), τους στόχους, τους πίνακες και τα βιβλία σου, ομαδοποιημένα ανά είδος – πάτα ένα για να πας κατευθείαν εκεί.",
    faq_a_my_day: "Η Μέρα μου ενώνει ό,τι παλιότερα ήταν η Μια Ματιά στο Σήμερα και η Ρουτίνα μου σε μία γραμμή χρόνου. Στο κάτω μέρος της αρχικής οθόνης βλέπετε πόσα έγιναν, τι είναι τώρα ή μετά (με γρήγορο ✓) και, δίπλα στον τίτλο, ένα ποτήρι νερό με +1. Πατήστε (ή σύρετε προς τα πάνω) για να ανοίξει όλη η μέρα: πάνω όσα δεν έχουν ώρα, μετά τα πάντα ανά ώρα – εργασίες, εκδηλώσεις και συναντήσεις από το ημερολόγιο, σταθερές εβδομαδιαίες ώρες, η σημερινή ρουτίνα, τα μικρά βήματα των στόχων σας και τα γεύματα του New Me – με μια γραμμή για το τώρα. Φιλτράρετε κατά Εργασίες, Ρουτίνα ή Συναντήσεις & εκδηλώσεις. Ένα ✓ εδώ είναι το ίδιο ✓ παντού (Η Ρουτίνα μου, Οι Στόχοι μου, ημερολόγιο) και ανοίγει μια μαργαρίτα στη γωνιά. Η «Επεξεργασία ρουτίνας» ανοίγει τη Ρουτίνα μου (υπάρχει και στο μενού) και η «＋ Προσθήκη για σήμερα» προσθέτει μια εργασία για σήμερα. Ένα άγγιγμα στον τίτλο «Η Μέρα μου» (ή στη μικρή μπάρα επάνω) το κλείνει ξανά.",
