    faq_a_new_me_tour: "Αμέσως μετά την αγορά και το σύντομο ερωτηματολόγιο, μια σύντομη ξενάγηση δείχνει το παιχνίδι: την πάνω μπάρα, την επόμενη αποστολή, την πρόκληση της εβδομάδας, το μαγικό σακίδιο και την πόρτα 1 προς το μυστικό δωμάτιο. Μπορεί να προβληθεί ξανά οποιαδήποτε στιγμή από ⚙️ Ρυθμίσεις > 🧭 Ξενάγηση στο New Me – εκεί μπορεί να αλλάξει και το πλήρες όνομα από το ερωτηματολόγιο. Πριν από την αγορά, δίπλα στο New Me στο μενού φαίνεται ένα 🔒, και ένα πάτημα ανοίγει μια σελίδα με όλα όσα περιλαμβάνονται.",
