    faq_a_new_me_advanced: "Η Προηγμένη λειτουργία ανοίγει με το δώρο, μετά από όλες τις 20 προκλήσεις, και ενεργοποιείται ή απενεργοποιείται στο 🎁 Το δώρο σου. Δίνει στο New Me χρυσή εμφάνιση, ελεύθερη σύνθεση μενού – κάθε αλλαγή δείχνει όλες τις επιλογές χωρίς όριο θερμίδων – και μια οθόνη 📊 Προηγμένα στατιστικά: θερμίδες των τελευταίων 30 ημερών σε σύγκριση με το πρόγραμμα, καλές ημέρες ανά ημέρα της εβδομάδας, την τάση του βάρους με εκτίμηση για το πότε επιτυγχάνεται ο στόχος, τους μέσους όρους του βραδινού απολογισμού και το ιστορικό των προκλήσεων.",
