    nm_gift_intro: "Και οι {n} προκλήσεις, βήμα βήμα. Να τι περίμενε:",
    nm_gift_title: "Το δώρο σου",
    faq_a_new_me_letter_gift: "Στην αρχή του New Me (ή αργότερα, στις Προκλήσεις) μπορεί να γραφτεί ένα γράμμα προς τον εαυτό σας στο μέλλον. Μόλις σφραγιστεί, δεν μπορεί να διαβαστεί ούτε να αλλάξει μέχρι να ανοίξει: στο μπουκάλι από τη θάλασσα στο μυστικό δωμάτιο ή στο τέλος και των 20 προκλήσεων – όπου περιμένει και ένα δώρο.",
    faq_q_new_me_letter_gift: "Τι είναι το γράμμα από το παρελθόν;",
    faq_a_new_me_challenges: "Οι 🏆 Προκλήσεις περιλαμβάνουν 20 προκλήσεις: 10 μεγάλες (όπως 5 ημέρες χωρίς ζάχαρη, μια εβδομάδα χωρίς υδατάνθρακες ή μείον 4 κιλά σε έναν μήνα – κάθε ημέρα θερμιδικό έλλειμμα, προπόνηση και χωρίς ζάχαρη) και 10 μίνι – μικρές συνήθειες για μια εβδομάδα, όπως καφές με κανέλα χωρίς ζάχαρη. Με την επιλογή μιας πρόκλησης ρωτάμε πότε ξεκινά: σήμερα, αύριο, την επόμενη εβδομάδα ή άλλη ημερομηνία. Μία μεγάλη και μία μίνι πρόκληση μπορούν να τρέχουν μαζί. Η πρόκληση σε εξέλιξη εμφανίζεται στην κορυφή του μενού και στη Μέρα μου, με ✓ για την ημέρα. Κάθε εβδομάδα πρόκλησης έχει μία ελεύθερη ημέρα (🍕) που δεν τη σπάει, και μια ημέρα χωρίς σημάδι μετράει ως ελεύθερη – μπορεί να σημειωθεί το σήμερα και το χθες. Κάποιες ημέρες σημειώνονται μόνες τους: μια προπόνηση 20 λεπτών στην Παρακολούθηση Προπόνησης ή τα γεύματα του μενού με ✓. Κάθε πρόκληση έχει ένα ⓘ με το τι ακριβώς μετράει (για παράδειγμα, την πλήρη λίστα υδατανθράκων) – μέσα στην ίδια την πρόκληση και δίπλα της στη Μέρα μου. Από κάτω, στο 🌱 Προσωπική ανάπτυξη, υπάρχουν 48 μικρές προκλήσεις για μία εβδομάδα (δεν μετράνε στις 20) – δείτε «Τι είναι η πρόκληση της εβδομάδας;».",
    faq_q_new_me_challenges: "Πώς λειτουργούν οι προκλήσεις στο New Me;",
