    nm_ch_completed_label: "προκλήσεις ολοκληρώθηκαν",
    nm_tile_challenges: "Προκλήσεις",
    faq_a_workout_calories: "Ναι. Κάθε προπόνηση παίρνει μια εκτίμηση των θερμίδων που κάηκαν – ανάλογα με το είδος, τη διάρκεια και το τελευταίο σας βάρος (στο τρέξιμο και την ποδηλασία και ανάλογα με την ταχύτητα, όταν δίνεται απόσταση). Εμφανίζεται στη λίστα προπονήσεων και στη μηνιαία σύνοψη (Κάηκαν) και προστίθεται στον θερμιδικό προϋπολογισμό εκείνης της ημέρας: στον Ημερήσιο Καταγραφέα Φαγητού, στις Μετρήσεις Θερμίδων και Βάρους και στον δακτύλιο του New Me. Είναι εκτίμηση, γι' αυτό εμφανίζεται με ~.",
    faq_q_workout_calories: "Μετράνε οι προπονήσεις στις θερμίδες της ημέρας;",
    faq_a_new_me_flexible_menu: "Ναι. Στο ερωτηματολόγιο και στις ρυθμίσεις επιλέγετε πόσα γεύματα την ημέρα – 2 γεύματα + ένα σνακ / 2 γεύματα + ένα ελαφρύ δείπνο / 2 γεύματα + ένα σνακ + ένα ελαφρύ δείπνο – και το ➖ στην κάρτα ενός γεύματος το αφαιρεί (μένουν τουλάχιστον 3)· η «Επαναφορά» το φέρνει πίσω. Σε κάθε περίπτωση οι θερμίδες της μέρας μένουν ίδιες: ό,τι αφαιρείται μοιράζεται στα υπόλοιπα γεύματα, και κάτω από κάθε γεύμα γράφει πόσο προστέθηκε και τι ταιριάζει. Η ✏️ Επεξεργασία ανοίγει το κείμενο του γεύματος – αλλάξτε ό,τι θέλετε (π.χ. χωρίς ψωμί ή με ένα αυγό ακόμα) και το AI ξαναϋπολογίζει θερμίδες και πρωτεΐνη. Η 🔄 Αλλαγή προτείνει επιλογές από το μενού, ⭐ Αποθηκευμένα και ✨ Γράψτε το· κάθε αλλαγή μπορεί να ισχύει μόνο για σήμερα ή από τώρα και πέρα. Και στο τέλος του «Όλη η μέρα» υπάρχει ➕ Προσθήκη φαγητού – γράψτε τι φαγώθηκε εκτός μενού και το AI το υπολογίζει και το προσθέτει στο σήμερα (✕ το διαγράφει).",
    faq_q_new_me_flexible_menu: "Μπορώ να αλλάξω τον αριθμό των γευμάτων στο New Me, ή να φάω δικό μου γεύμα;",
    daily_calorie_mini_burn: "+🔥 {amount} από προπόνηση",
