    sport_total_kcal: "Κάηκαν",
    nm_swap_ai_too_big: "Λίγο περισσότερο από όσο απομένει για σήμερα – χωράνε έως ~{n} θερμίδες. Μπορείτε να το καταγράψετε κι έτσι – τα υπόλοιπα σημερινά γεύματα μικραίνουν για ισορροπία – ή να επιλέξετε μικρότερη μερίδα.",
