    nb_shelf_delete_confirm: "Θα διαγραφεί και ό,τι υπάρχει μέσα (📓 {nb} · ▦ {tb} · ✅ {ts}). Για να κρατήσετε κάτι, μετακινήστε το πρώτα σε άλλη τσέπη.",
