    goal_share_heading: "Πέτυχα έναν στόχο!",
    share_footer_sent_from: "Στάλθηκε από το NOT10.ai",
    faq_a_goal_days_challenge: "Στην ενότητα «Οι Στόχοι μου» πατήστε ＋ (ή το έτοιμο παράδειγμα «🔥 8 ημέρες»), επιλέξτε «📆 Πρόκληση ημερών», εισαγάγετε πόσες ημέρες και προσθέστε τι κάνετε κάθε μέρα (π.χ. «Περπάτημα 30 λεπτών», «Φαγητό σύμφωνα με το μενού μου»). Κάθε μέρα, τσεκάρετε τις εργασίες της ημέρας κάτω από το μονοπάτι της πρόκλησης – όταν τσεκαριστούν όλες, η μέρα μετράει, το μονοπάτι προχωρά μία πέτρα και η σειρά σας 🔥 μεγαλώνει (χωρίς καθημερινές εργασίες υπάρχει ένα μόνο κουμπί «✓ Το έκανα σήμερα»). Το κουμπί 🔁 δίπλα σε μια εργασία την προσθέτει στην ενότητα «Η Ρουτίνα μου» σε ώρα της επιλογής σας: το τσεκάρισμα εκεί την τσεκάρει και στον στόχο, και αντίστροφα. Τα ορόσημα ενός κανονικού στόχου μπορούν να προστεθούν στη Ρουτίνα μου με τον ίδιο τρόπο.",
    faq_q_goal_days_challenge: "Πώς ορίζω μια πρόκληση όπως «8 ημέρες περπάτημα και υγιεινή διατροφή» και τη συνδέω με τη Ρουτίνα μου;",
