    nm_drink_missing: "Εισαγάγετε όνομα ροφήματος και θερμίδες",
    nm_drink_more: "+ Άλλο ρόφημα",
    nm_drink_add: "Προσθήκη",
    nm_drink_name_ph: "Ρόφημα (π.χ. χυμός)",
    nm_drinks_hint: "Αρκεί να πληκτρολογήσετε το ρόφημα – οι θερμίδες υπολογίζονται αυτόματα και ο αριθμός μπορεί να αλλάξει.",
    nm_slot_drinks: "Ροφήματα",
    faq_a_new_me_tracking: "Πατήστε την επόμενη αποστολή στο πάνω μέρος του New Me και μετά το ✓ Έφαγα για να σημειώσετε το επόμενο γεύμα ως φαγωμένο – ολόκληρο το μενού με ✓ σε κάθε γεύμα υπάρχει στην ενότητα «Όλη η μέρα», στο πλάι, και τα σημερινά γεύματα εμφανίζονται επίσης στη Μέρα μου στην αρχική οθόνη – ένα πάτημα σε ένα από αυτά εκεί (ή το ποντίκι από πάνω) δείχνει ακριβώς τι θα φάτε, με ✓ και Αλλαγή. Όλα συγχρονίζονται με τον Ημερήσιο Καταγραφέα Φαγητού: τα γεύματα του προγράμματος, τα ροφήματα και ό,τι προσθέτετε αλλού (για παράδειγμα έναν καφέ από τη γρήγορη προσθήκη) μετρώνται μαζί στο New Me και στη Μέρα μου – τίποτα από όσα έχετε ήδη γράψει δεν αντικαθίσταται, και η αφαίρεση ενός ✓ αφαιρεί μόνο το κομμάτι του New Me. Όταν σημειωθούν όλα τα σημερινά γεύματα, γίνεται μια μικρή γιορτή. Στα «Ροφήματα» καταγράφετε τα ροφήματα της ημέρας – όλα μαζί έως ~150 kcal, δηλαδή περίπου 3 ροφήματα έως ~50 kcal το καθένα. Αρκεί να γράψετε το όνομα του ροφήματος και οι θερμίδες συμπληρώνονται αυτόματα με AI. Οι δύο γραμμές καφέ/τσαγιού έχουν επίσης πεδίο «Γάλα; Πόσο;» (για παράδειγμα «λίγο» ή «50 ml»), και ο υπολογισμός ενημερώνεται· ο αριθμός μπορεί να αλλάξει πριν από την προσθήκη αλλά και μετά. Ένα ρόφημα με όνομα και θερμίδες αποθηκεύεται αυτόματα μόλις προχωρήσετε – το πάτημα στο Προσθήκη είναι προαιρετικό. Πατήστε ☆ δίπλα σε ένα ρόφημα για να το αποθηκεύσετε ως σταθερό – τα σταθερά ροφήματα εμφανίζονται ως κουμπιά πάνω στην κάρτα Ροφήματα, και ένα πάτημα τα προσθέτει στη μέρα. Το ⭐ αποθηκεύει ένα γεύμα ως αποθηκευμένο γεύμα. Ο «Ημερήσιος πίνακας» δείχνει τι φάγατε με θερμίδες και πρωτεΐνη. Το μικρό 💎 δίπλα στη λειτουργία εστίασης, στο πάνω μέρος της αρχικής οθόνης, το ανοίγει απευθείας. Οι τιμές θερμίδων και πρωτεΐνης είναι εκτιμήσεις AI και μπορεί να περιέχουν λάθη. Δεν τα φάγατε όλα; Κάτω από ένα σημειωμένο γεύμα, το «Δεν τα έφαγα όλα;» αφαιρεί ένα τέταρτο, το μισό ή τα τρία τέταρτα της μερίδας – ή ό,τι γράψετε, με υπολογισμό – και οι θερμίδες της ημέρας ενημερώνονται.",
    faq_q_new_me_tracking: "Πώς λειτουργούν το ✓, οι αλλαγές και οι θερμίδες στο New Me;",
    faq_a_new_me_what: "Το New Me είναι ένα ξεχωριστό πρόγραμμα ημερήσιου μενού με δύο έτοιμα προγράμματα – 1.300 ή 1.500 θερμίδων – από 2 κύρια γεύματα και 2 σνακ, με 3 επιλογές για το καθένα. Περιλαμβάνει όλο το Premium. Τιμή: $11.99 τον μήνα (ακύρωση οποτεδήποτε) ή $99.99 μία φορά, εφ' όρου ζωής. Ανοίγει από το 💎 New Me στο μενού. Πριν την έναρξη υπάρχει ένα σύντομο ερωτηματολόγιο που ξεκινά με μια ιατρική δήλωση αποποίησης που πρέπει να γίνει αποδεκτή. Το πρόγραμμα είναι μόνο γενική πληροφόρηση και δεν αντικαθιστά γιατρό ή κλινικό διαιτολόγο.",
    faq_q_new_me_what: "Τι είναι το New Me και πώς το αποκτώ;",
