    nm_sales_f2: "Ένα ημερήσιο ✓ για κάθε γεύμα, και πόσες θερμίδες απομένουν σήμερα",
    nm_sales_f1: "Δύο έτοιμα προγράμματα (1.300 / 1.500 kcal) με τουλάχιστον 3 επιλογές για κάθε γεύμα",
    nm_sales_subtitle: "Ένα έτοιμο ημερήσιο μενού 1.300 ή 1.500 θερμίδων – με παρακολούθηση, έξυπνες αλλαγές, προκλήσεις και μια πορεία προόδου.",
    faq_a_categories_menu: "Το μενού της εφαρμογής μπορεί να εμφανίζεται με έναν από δύο τρόπους, και επάνω εμφανίζεται μόνο ένα κουμπί: ☰ λίστα (προεπιλογή) ή ▦ μεγάλα πλακίδια - Σχεδιασμός και Ημερολόγιο, Λίστες, Στόχοι και Πρόοδος, Διατροφή και Μετρήσεις, Αθλητισμός, και Έξοδα και Έσοδα· πατήστε ένα πλακίδιο για να δείτε τι περιέχει και μετά πατήστε αυτό που χρειάζεστε. Για εναλλαγή, ανοίξτε το μενού και πατήστε το μικρό κουμπί στο επάνω μέρος του: το ▦ στο μενού λίστας περνά στα πλακίδια, και το ☰ στο μενού πλακιδίων επιστρέφει στη λίστα. Το μενού πλακιδίων έχει επίσης ένα κουμπί ⚙️ για τις Ρυθμίσεις. Η επιλογή σας αποθηκεύεται και ισχύει σε όλες τις συσκευές σας.",
    faq_q_categories_menu: "Πώς γίνεται εναλλαγή ανάμεσα στο μενού λίστας ☰ και στο μενού πλακιδίων ▦;",
    new_me_coming_soon: "Ένα νέο προσωπικό πρόγραμμα έρχεται - σύντομα διαθέσιμο.",
    categories_menu_title: "Όλες οι κατηγορίες",
    hamburger_group_planning: "Σχεδιασμός και Ημερολόγιο",
    routine_overview_no_checks: "Δεν υπάρχουν ακόμη τσεκαρίσματα αυτόν τον μήνα - πατήστε το ✓ δίπλα στα στοιχεία της ρουτίνας σας τις μέρες που τα κάνετε.",
    faq_a_finance_cycle_day: "Από προεπιλογή η σύνοψη του προϋπολογισμού σας μηδενίζεται την 1η κάθε ημερολογιακού μήνα. Αν πληρώνεστε άλλη μέρα (ας πούμε στις 10), ορίστε αυτή τη μέρα εδώ - τότε η μηνιαία σύνοψη, το ιστορικό και ο στόχος προϋπολογισμού σας θα μετρούν από εκείνη τη μέρα έως την ίδια μέρα του επόμενου μήνα, αντί από την 1η έως το τέλος του μήνα.",
    faq_q_finance_cycle_day: "Τι κάνει η ρύθμιση 'Ημέρα μηδενισμού μηνιαίου προϋπολογισμού';",
    faq_a_quick_note_view_full_lists: "Στο μενού ☰ είναι ακριβώς εκεί οι Σημειώσεις και η Λίστα Αγορών. Στο παράθυρο Γρήγορες Σημειώσεις (στη Λειτουργία εστίασης), τα μικρά 📝 και 🛒 δίπλα στην Προσθήκη οδηγούν επίσης εκεί, και το 🍎 καταγράφει γρήγορα ένα από τα αποθηκευμένα γεύματά σου.",
    faq_q_quick_note_view_full_lists: "Πώς βλέπω όλες τις Σημειώσεις μου ή ολόκληρη τη Λίστα Αγορών από τις Γρήγορες Σημειώσεις;",
