    daily_focus_p2_d3_s1: "Να διατηρώ τη σύνδεση με τους στόχους μου και να εμβαθύνω τη συγκέντρωσή μου", daily_focus_p2_d3_s2: "Να επιβραδύνω για να ενεργώ με τη μέγιστη ακρίβεια και ποιότητα", daily_focus_p2_d3_s3: "Να διατηρώ πλήρη σαφήνεια σε κάθε συζήτηση και συντονισμό", daily_focus_p2_d3_s4: "Να επικεντρώνομαι σε μία μόνο ενέργεια μέχρι να ολοκληρωθεί πλήρως", daily_focus_p2_d3_s5: "Να αντλώ γρήγορα ένα μάθημα από κάθε πρόκληση και να συνεχίζω μπροστά",
