    daily_focus_p2_d6_s1: "Να διατηρώ τη σωστή ισορροπία ανάμεσα στην εργασία και την ξεκούραση", daily_focus_p2_d6_s2: "Να ανακεφαλαιώνω τις τελευταίες μέρες με παρουσία και μαθήματα που αποκόμισα", daily_focus_p2_d6_s3: "Να κρατάω υπομονή με μια διαδικασία που χτίζεται βήμα-βήμα", daily_focus_p2_d6_s4: "Να εκτιμώ όλα όσα έχω καταφέρει και να χαλαρώνω ήρεμα", daily_focus_p2_d6_s5: "Να γεμίζω με ικανοποίηση από την πειθαρχία που έδειξα",
    daily_focus_p2_d7_s1: "Να αφιερώνω την ημέρα στην επαναφόρτιση και την πλήρη ανανέωση", daily_focus_p2_d7_s2: "Να ακούω την εσωτερική μου επιθυμία και να κάνω πράγματα που με γεμίζουν", daily_focus_p2_d7_s3: "Να αναγνωρίζω πλήρως την επιμονή μου και τη διαδρομή που έχω διανύσει", daily_focus_p2_d7_s4: "Να αφήνω όλα τα σχέδια και να απολαμβάνω την πνευματική ελευθερία", daily_focus_p2_d7_s5: "Να είμαι ευγνώμων για την ικανότητα να επιμένω, να μαθαίνω και να βελτιώνομαι",
    daily_focus_p3_d1_s1: "Να διαφυλάττω έναν χώρο εσωτερικής ασφάλειας και δύναμης", daily_focus_p3_d1_s2: "Να ακούω τη φωνή που με ωθεί να τολμώ και να εξελίσσομαι", daily_focus_p3_d1_s3: "Να επιλέγω έναν θαρραλέο εσωτερικό διάλογο που ανοίγει δυνατότητες", daily_focus_p3_d1_s4: "Να κάνω ένα ουσιαστικό βήμα έξω από τη ζώνη άνεσής μου", daily_focus_p3_d1_s5: "Να συντονίζομαι για να δρω στο υψηλότερο επίπεδό μου",
    daily_focus_p3_d2_s1: "Να επενδύω την ενέργειά μου σε ευκαιρίες και ανάπτυξη", daily_focus_p3_d2_s2: "Να παίρνω αποφάσεις με τόλμη και να δρω με αποφασιστικότητα", daily_focus_p3_d2_s3: "Να βλέπω τις προκλήσεις ως ευκαιρία να αποδείξω την ικανότητά μου", daily_focus_p3_d2_s4: "Να επιλέγω θαρραλέα δράση που μεγαλώνει την ικανότητά μου", daily_focus_p3_d2_s5: "Να εκτιμώ την προθυμία μου να δοκιμάζω καινούργια πράγματα",
