    daily_focus_p3_d6_s1: "Να ανοίγω έναν χώρο σεβασμού για ηρεμία και πλήρη ανάκαμψη", daily_focus_p3_d6_s2: "Να παρατηρώ την πρόοδό μου με περηφάνια για τη δύναμη που ανακάλυψα", daily_focus_p3_d6_s3: "Να πιστεύω πως τα αποτελέσματα έρχονται σε όσους τολμούν και επιμένουν", daily_focus_p3_d6_s4: "Να χαλαρώνω με ικανοποίηση, γνωρίζοντας πως έδωσα το μέγιστο", daily_focus_p3_d6_s5: "Να φορτίζω τις μπαταρίες μου για να συνεχίσω να κατακτώ νέες κορυφές",
